import {validateRecovery,fulfillmentCsv,recoveryEnvelope} from './recovery-data.js';
export {validateRecovery,fulfillmentCsv,recoveryEnvelope} from './recovery-data.js';
const errorMessages={proof_files:'An attached payment proof could not be copied. The previous verified backup remains available.',access:'Google access was denied. Check the service-account sharing on the spreadsheet and both proof archives.',api_disabled:'Google Sheets or Drive API is not enabled for the configured Google project.',quota:'Google temporarily limited requests. The scheduled backup will retry.',configuration:'The Google connection or backup tabs need attention.',too_large:'The backup exceeds its size limit. Download the current order data manually and arrange additional proof storage.',readback:'The saved recovery data could not be verified. Previous history is retained.',network:'The last backup could not finish. It will retry automatically.'};
export function mountBackup(root,{api,owner,esc,money}){
 if(!owner){root.innerHTML='<p class="notice">Only the shop owner can download order backups.</p>';return;}
 let snapshot=null,busy=false;
 root.innerHTML='<div class="view-heading"><div><span class="eyebrow">BUSINESS RECOVERY</span><h1>Order backup</h1><p>Keep a copy of the orders your customers are waiting for.</p></div></div><section class="panel backup-panel"><h2>Automatic Google Drive backup</h2><p>Paid and payment-under-review orders awaiting pickup or delivery, including overdue orders. Under review is clearly labelled and does not mean payment is confirmed. Completed orders leave the active Orders and Items tabs on the next successful sync.</p><div data-drive-status role="status" aria-live="polite">Checking connection…</div><div data-proof-link></div><div class="row-actions"><button class="button" data-drive-sync disabled>Back up now</button><button class="button button-secondary" data-drive-refresh>Refresh status</button><a class="button button-secondary" data-drive-open hidden target="_blank" rel="noopener noreferrer">Open backup sheet ↗</a></div><p class="help-text">The server checks every five minutes while this page and your computer are closed. Unchanged records are skipped; a daily refresh repairs accidental sheet changes. Google Sheets does not change your website orders.</p><p>The Recovery tab keeps paid-order history, orders under payment review, affiliate attribution, commissions, payouts, payment records and stock allocations. History retains earlier snapshots for 30 days.</p></section><section class="panel backup-panel"><h2>Download a copy</h2><p>Save the active fulfilment list and detailed order data whenever you need them. Download the linked payment-proof archive separately to keep the actual attached images.</p><button class="button" data-backup-prepare>Prepare current backup</button><div data-backup-status role="status" aria-live="polite"></div><div data-backup-downloads hidden><div class="row-actions"><button class="button" data-backup-json>Download order data</button><button class="button button-secondary" data-backup-csv>Download fulfilment list</button></div></div><p class="help-text">Manual downloads are separate copies. Prepare a new copy to include later updates. Keep downloaded files private.</p><p><a href="https://drive.google.com/drive/folders/1Sh49xlV0ScTwUrH6UC_5EMNehTHBoSIh" target="_blank" rel="noopener noreferrer">Open private backup folder ↗</a></p></section><section class="panel backup-panel"><h2>What this protects</h2><p>This is an operational recovery copy, including paid-order history and affiliate records. It supplements a complete database backup. Attached payment proofs for active paid and under-review orders are copied as actual files in a private ZIP archive. The current and previous archive alternate between A and B. Older History snapshots retain data, but do not guarantee an older proof archive is still available. Affiliate payout-proof images are not bundled.</p><p class="help-text">An outage can prevent new copies. Check the last successful backup before relying on it. The connection reports success only after the recovery data has been read back and verified.</p></section>';
 const q=s=>root.querySelector(s),status=q('[data-backup-status]'),drive=q('[data-drive-status]');
 const date=value=>new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'medium'}).format(new Date(value));
 const showConnection=value=>{const messages={disconnected:'Automatic backup is not connected.',pending:'Waiting for the first successful server backup.',connected:value.pending?'Connected · changes are waiting for the next backup.':'Connected · the latest scheduled changes are backed up.',stale:'Backup needs attention: changes have been waiting for more than 15 minutes.',error:errorMessages[value.last_error]||errorMessages.network};drive.innerHTML='<p class="notice">'+esc(messages[value.state]||'Connection status unavailable.')+(value.last_success_at?'<br>Last successful backup: '+esc(date(value.last_success_at))+' · Manila time.':'')+(value.active_count!=null?'<br>'+value.active_count+' active orders · '+(value.active_review_count||0)+' under payment review · '+value.paid_history_count+' paid orders in recovery history.':'')+'</p>';q('[data-drive-sync]').disabled=!value.enabled||busy;q('[data-proof-link]').innerHTML=value.proof_archive_id?'<p><a target="_blank" rel="noopener noreferrer" href="https://drive.google.com/file/d/'+encodeURIComponent(value.proof_archive_id)+'/view">Open payment-proof backup ('+(value.proof_count||0)+' '+(value.proof_count===1?'file':'files')+') ↗</a></p>':'';const link=q('[data-drive-open]');link.hidden=!value.spreadsheet_id;if(value.spreadsheet_id)link.href='https://docs.google.com/spreadsheets/d/'+encodeURIComponent(value.spreadsheet_id)+'/edit';};
 const refresh=async()=>{q('[data-drive-refresh]').disabled=true;try{const value=await api('order_backup_status');if(root.isConnected)showConnection(value);}catch{drive.textContent='Backup status could not load. Manual backup remains available.';}finally{q('[data-drive-refresh]').disabled=false;}};
 q('[data-drive-refresh]').onclick=refresh;
 q('[data-drive-sync]').onclick=async()=>{if(busy)return;busy=true;q('[data-drive-sync]').disabled=true;drive.textContent='Requesting a fresh backup…';try{await api('order_backup_sync_now');drive.textContent='Backup requested. Refresh status shortly to confirm it finished.';}catch(e){drive.textContent=e.message||'The backup request failed. Please try again.';}finally{busy=false;q('[data-drive-sync]').disabled=false;}};
 void refresh();
 q('[data-backup-prepare]').onclick=async()=>{const button=q('[data-backup-prepare]');button.disabled=true;button.textContent='Preparing backup…';snapshot=null;q('[data-backup-downloads]').hidden=true;status.textContent='Reading current paid orders, payment reviews and affiliate records…';try{const data=validateRecovery(await api('paid_order_recovery'));if(!root.isConnected)return;snapshot=data;status.innerHTML='<p class="notice success"><strong>'+data.active_count+' '+(data.active_count===1?'order':'orders')+' awaiting service · '+esc(money(data.active_total_cents))+'</strong><br>'+data.paid_history_count+' paid orders in recovery history · '+data.affiliate_ledger.length+' commission entries.<br>Prepared '+esc(date(data.generated_at))+' · Manila time.</p>';q('[data-backup-downloads]').hidden=false;}catch(e){status.textContent=e.message||'Backup could not load. Previous files were not changed.';}finally{button.disabled=false;button.textContent='Prepare current backup';}};
 const download=(content,type,extension,at)=>{const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download='elio-'+(extension==='csv'?'active-fulfilment':'paid-order-recovery')+'-'+at.replace(/[:.]/g,'-')+'.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
 q('[data-backup-json]').onclick=async()=>{const current=snapshot;if(current)download(JSON.stringify(await recoveryEnvelope(current),null,2),'application/json','json',current.generated_at);};
 q('[data-backup-csv]').onclick=()=>{const current=snapshot;if(current)download(fulfillmentCsv(current),'text/csv;charset=utf-8','csv',current.generated_at);};
}
